insert into tickets (ticket_ref,created_at,cliente,pais,asunto,cuerpo,es_set_prueba,etiqueta_severidad,etiqueta_origen,ambiguo,nota_etiqueta) values
('T01',now()-interval '1380 minutes','Finexa (ficticio)','CO','Usuario rechazado 3 veces','Hola, un usuario nos escribe molesto porque lo rechazaron 3 veces y el motivo dice blurry_image. ¿Lo pueden aprobar manualmente? Proceso IDP-CO-48211.',true,'P3','usuario_final',false,'Un solo usuario; foto ilegible.'),
('T02',now()-interval '1320 minutes','PagoYa (ficticio)','MX','Muchos process_started_late','Desde el lunes vemos muchos procesos declinados con process_started_late. Enviamos los links de validación por correo a las 8 a. m. y la mayoría de los usuarios los abren en la tarde. ¿Por qué pasa esto?',true,'P3','usuario_final',true,'Ambiguo: el código es de usuario final pero la causa de fondo es cuándo envía los links el cliente (integración). Decide tú.'),
('T03',now()-interval '1260 minutes','Crédito Sur Perú (ficticio)','PE','DNI vigente sale vencido','Un usuario fue declinado con document_has_expired pero nos manda foto de su DNI y la fecha de caducidad es 2029. Proceso IDP-PE-90314. ¿Qué pasó?',true,'P3','indeterminado',true,'Ambiguo: puede ser mala lectura de la fecha (plataforma) o documento distinto. Faltan datos para decidir.'),
('T04',now()-interval '1200 minutes','Ahorro Austral (ficticio)','CL','RUT no encontrado','Una usuaria quedó declinada con document_unregistered. Dice que renovó su cédula la semana pasada. Proceso IDP-CL-33019.',true,'P3','usuario_final',false,'Un caso; documento recién renovado aún no aparece en la fuente.'),
('T05',now()-interval '1140 minutes','Banco Solar (ficticio)','BR','Selfie rechazada','Um usuário foi recusado com photo_of_photo, mas ele diz que tirou a selfie ao vivo. Processo IDP-BR-11872.',false,'P3','usuario_final',false,'Un caso; fuera del set de evaluación.'),
('T06',now()-interval '1080 minutes','Finexa (ficticio)','CO','Usuario sin intentos','El usuario del proceso IDP-CO-48377 dice que ya no le deja intentar más, sale max_retries_reached. ¿Cómo hacemos para que lo intente otra vez?',false,'P3','usuario_final',false,'Fuera del set de evaluación.'),
('T07',now()-interval '1020 minutes','PagoYa (ficticio)','MX','Rostro no coincide','Un usuario con lentes no pasa similarity_threshold_not_passed, ya lo intentó dos veces. Proceso IDP-MX-55102.',false,'P3','usuario_final',false,'Fuera del set de evaluación.'),
('T08',now()-interval '960 minutes','Crédito Sur Perú (ficticio)','PE','No llega el código SMS','Un usuario dice que el código que le llega no funciona, sale wrong_verification_code. Proceso IDP-PE-90420.',false,'P3','usuario_final',false,'Fuera del set de evaluación.'),
('T09',now()-interval '900 minutes','PagoYa (ficticio)','MX','¿Qué significa liveness?','¿Nos pueden explicar qué significa liveness_verification_not_passed? Queremos poner un texto de ayuda para nuestros usuarios en la app.',true,'P4','usuario_final',false,'Pregunta general sin falla activa.'),
('T10',now()-interval '840 minutes','Ahorro Austral (ficticio)','CL','Subida de rechazos por blurry_image','Desde ayer en producción el 40% de nuestros procesos sale declinado con blurry_image. Antes era cerca del 5%. No cambiamos nada en nuestra app.',true,'P2','indeterminado',true,'Ambiguo: puede ser cambio en la plataforma o en dispositivos; impacto parcial en producción.'),
('T11',now()-interval '25 minutes','Finexa (ficticio)','CO','URGENTE validaciones caídas','Desde las 9:10 a. m. todas las validaciones de cédula salen declined con government_database_unavailable. Estamos en producción y tenemos el onboarding detenido.',true,'P1','fuente_externa_gobierno',false,'Incidente externo CO (1 de 4).'),
('T12',now()-interval '20 minutes','Cootransfer (ficticio)','CO','Validaciones lentas','Las validaciones de documento están tardando mucho y algunas salen con government_database_unavailable. Producción. Procesos IDP-CO-48801 y IDP-CO-48807.',true,'P2','fuente_externa_gobierno',false,'Incidente externo CO (2 de 4); parcial.'),
('T13',now()-interval '15 minutes','Monedero Ya (ficticio)','CO','No podemos validar a nadie','Ningún cliente nuevo puede terminar el registro, todas las validaciones de identidad fallan contra la Registraduría. Producción, cientos de usuarios esperando.',true,'P1','fuente_externa_gobierno',false,'Incidente externo CO (3 de 4).'),
('T14',now()-interval '10 minutes','Finexa (ficticio)','CO','Background checks demorados','Los background checks de personas en Colombia llevan más de una hora en proceso. Normalmente salen en minutos. Producción.',true,'P2','fuente_externa_gobierno',false,'Incidente externo CO (4 de 4); checks demorados por la fuente.'),
('T15',now()-interval '700 minutes','PagoYa (ficticio)','MX','Checks de CURP en proceso','En sandbox los checks con CURP se quedan en proceso y no terminan. Estamos probando la integración, aún no salimos a producción.',true,'P3','fuente_externa_gobierno',false,'Fuente RENAPO lenta; sandbox.'),
('T16',now()-interval '650 minutes','Banco Solar (ficticio)','BR','Consultas de CPF lentas','As consultas de CPF estão demorando muito e alguns checks ficam pendentes. Estamos em produção, parte dos clientes novos não consegue avançar.',true,'P2','fuente_externa_gobierno',false,'Receita Federal lenta; parcial en producción.'),
('T17',now()-interval '600 minutes','Cobranzas Norte (ficticio)','MX','Campaña no salió','Meta marcó nuestra línea con calidad baja y hoy no salió la campaña de cobranza. Es nuestra línea de producción.',true,'P2','meta_whatsapp',false,'Calidad baja; no hay suspensión total.'),
('T18',now()-interval '580 minutes','Monedero Ya (ficticio)','CO','Línea de WhatsApp suspendida','Nuestra línea de WhatsApp de producción aparece suspendida desde esta mañana. No podemos enviar ningún mensaje a los clientes, todo el canal está caído.',true,'P1','meta_whatsapp',false,'Canal principal caído por decisión de Meta.'),
('T19',now()-interval '560 minutes','Ahorro Austral (ficticio)','CL','Plantilla rechazada','Meta rechazó la plantilla de recordatorio de pago que usamos todos los días. Sin ella no podemos avisar a los clientes de sus cuotas.',true,'P2','meta_whatsapp',false,'Plantilla crítica rechazada.'),
('T20',now()-interval '540 minutes','Crédito Sur Perú (ficticio)','PE','Subir límite de mensajes','Tenemos un límite de 250 conversaciones al día y queremos llegar a más clientes. ¿Cómo hacemos para subirlo?',true,'P4','meta_whatsapp',true,'Ambiguo: es consulta (P4) y el límite lo define Meta; podría verse como no_aplica.'),
('T21',now()-interval '520 minutes','Cootransfer (ficticio)','CO','Mensajes no llegan','Algunos usuarios dicen que no les llegan nuestros mensajes de WhatsApp desde ayer. No sabemos si es Meta o ustedes. Producción.',true,'P2','indeterminado',true,'Ambiguo: puede ser Meta (calidad o límite) o plataforma; faltan datos.'),
('T22',now()-interval '500 minutes','Cobranzas Norte (ficticio)','MX','Verificación del negocio','Nuestra verificación de Business Manager sigue pendiente y no pasamos del límite inicial. ¿Ustedes pueden acelerarla?',false,'P3','meta_whatsapp',false,'Fuera del set de evaluación.'),
('T23',now()-interval '480 minutes','Finexa (ficticio)','CO','No puedo guardar el flujo','Estoy editando un flujo en Flowbuilder y al guardar sale un error por la variable user_phone_number. Antes funcionaba.',true,'P3','integracion_cliente',false,'Migración BSUID; el cliente debe cambiar el flujo.'),
('T24',now()-interval '460 minutes','PagoYa (ficticio)','MX','Teléfono vacío en automatizaciones','Desde la semana pasada el teléfono del usuario llega vacío en nuestra automatización y nuestro CRM no crea los leads. Producción.',true,'P2','integracion_cliente',false,'Migración BSUID; impacto en producción.'),
('T25',now()-interval '440 minutes','Crédito Sur Perú (ficticio)','PE','Qué es WhatsApp User ID','¿Qué es la variable WhatsApp User ID y en qué se diferencia del número de teléfono?',false,'P4','integracion_cliente',false,'Fuera del set de evaluación.'),
('T26',now()-interval '420 minutes','Ahorro Austral (ficticio)','CL','Webhook sin teléfono','Nuestro flujo publicado ya no manda el teléfono a nuestro webhook en algunos usuarios. Lo usamos para identificar al cliente. Producción.',true,'P2','integracion_cliente',false,'Migración BSUID; parcial en producción.'),
('T27',now()-interval '400 minutes','Monedero Ya (ficticio)','CO','Unauthorized en links','Nuestros usuarios ven ''unauthorized'' cuando abren el link de validación que les mandamos ayer por correo.',true,'P2','integracion_cliente',false,'API key temporal expirada; varios usuarios.'),
('T28',now()-interval '380 minutes','Cobranzas Norte (ficticio)','MX','Error 401 al consultar procesos','Cuando consultamos el resultado de un proceso nos sale 401. Usamos la misma API key temporal que le damos al usuario.',false,'P3','integracion_cliente',false,'Fuera del set de evaluación.'),
('T29',now()-interval '360 minutes','Ahorro Austral (ficticio)','CL','Cámara no abre en la app','Desde que publicamos la nueva versión de nuestra app Android, la cámara no abre en la validación para ningún usuario. El flujo corre dentro de un WebView. Producción.',true,'P2','integracion_cliente',false,'WebView sin permiso de cámara; todos los usuarios de la app.'),
('T30',now()-interval '340 minutes','Crédito Sur Perú (ficticio)','PE','Cámara negra en iframe','Estamos integrando el flujo en un iframe de nuestra web y en iPhone la cámara se ve negra. Estamos en sandbox.',false,'P3','integracion_cliente',false,'Fuera del set de evaluación.'),
('T31',now()-interval '320 minutes','Banco Solar (ficticio)','BR','Cámara en un celular','Un usuario con un celular antiguo no logra abrir la cámara para la validación. Proceso IDP-BR-11901.',false,'P3','usuario_final',false,'Fuera del set de evaluación.'),
('T32',now()-interval '28 minutes','PagoYa (ficticio)','MX','Webhooks no llegan','Desde las 10:05 no recibimos ningún webhook de procesos de identidad terminados en producción. Nuestro endpoint responde 200 en las pruebas y no cambiamos nada.',true,'P1','truora',false,'Incidente de plataforma MX (1 de 3).'),
('T33',now()-interval '22 minutes','Cobranzas Norte (ficticio)','MX','Sin webhooks de validación','Hace media hora dejamos de recibir los webhooks de validaciones exitosas. Producción. Nuestro servidor está arriba y otros servicios sí nos llegan.',true,'P1','truora',false,'Incidente de plataforma MX (2 de 3).'),
('T34',now()-interval '16 minutes','Monedero Ya (ficticio)','MX','Webhooks atrasados','Los webhooks de identidad nos están llegando con mucho retraso o no llegan desde hace un rato. Producción en México.',true,'P2','truora',false,'Incidente de plataforma MX (3 de 3); impacto parcial.'),
('T35',now()-interval '300 minutes','Finexa (ficticio)','CO','No llega el webhook','Ayer cambiamos la URL de nuestro webhook y desde entonces no nos llega nada. En nuestros logs vemos que las llamadas entran con 404. Producción.',true,'P2','integracion_cliente',false,'Endpoint del cliente devuelve 404 tras su cambio de URL.'),
('T36',now()-interval '280 minutes','Banco Solar (ficticio)','BR','Documento assinado pendente','Um documento foi assinado por todos os signatários, mas no painel continua como pendente há 3 horas. Documento DOC-BR-7781.',true,'P3','truora',false,'Comportamiento distinto al documentado en un caso.'),
('T37',now()-interval '260 minutes','Banco Solar (ficticio)','BR','Assinaturas recusadas','Todas as assinaturas do nosso fluxo de contrato estão sendo recusadas com missing_required_attached_validations. Produção.',true,'P2','integracion_cliente',false,'Configuración del flujo de firma.'),
('T38',now()-interval '240 minutes','Banco Solar (ficticio)','BR','Segundo signatário','Como faço para adicionar um segundo signatário ao mesmo documento?',false,'P4','no_aplica',false,'Fuera del set de evaluación.'),
('T39',now()-interval '220 minutes','Finexa (ficticio)','CO','Revisión manual atrasada','Tenemos 30 documentos en revisión manual desde hace 21 horas y los usuarios siguen esperando. Contratamos la revisión con el equipo de Truora. Producción.',true,'P2','truora',false,'SLA de 24 h en riesgo.'),
('T40',now()-interval '200 minutes','PagoYa (ficticio)','MX','Procesos vencidos en revisión','Ayer varios procesos terminaron con manual_review_not_performed. Tenemos contratada la revisión manual de Truora. Los usuarios tuvieron que empezar de nuevo.',true,'P2','truora',false,'SLA incumplido por la revisión de Truora.')
